 if(interior)return [p('production','Plan production',-3.8,2.8,-1.8),p('machines','Equipment',1,2.2,-3.4),p('staff','Your team',-5.5,1.7,2.7),p('inventory','Ingredients',-6.5,2.4,-3.7),p('research','Recipe bench',5.4,2.2,-2.9),p('dispatch','Pack & dispatch',4.2,2.1,3.5)];
